// Kiểm bộ đèn trên GPU thật: node lightsets.mjs <repo> <distDir>
import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';
import path from 'node:path';

const repo = process.argv[2], dist = process.argv[3];
const require = createRequire(path.join(repo, 'package.json'));
const { chromium } = require('playwright');
const lib = await import(pathToFileURL(path.join(repo, 'tests/lib.mjs')).href);
const srv = await lib.serveDir(dist);
const browser = await chromium.launch({ headless: true, args: ['--use-angle=d3d11', '--ignore-gpu-blocklist', '--enable-gpu', '--disable-gpu-vsync', '--disable-frame-rate-limit'] });
const { page, errors } = await lib.openApp(browser, srv.url + '?perf', { width: 1920, height: 1080 });
try {
  const st = await page.evaluate(() => ({ firstFrameMs: Math.round(window.__app.perf.firstFrameMs), programs: window.__app.renderer.info.programs.length }));
  console.log('khởi động', st);
  const state = async (label) => {
    await lib.frames(page, 2);
    const r = await page.evaluate(() => { const A = window.__app; return { set: A.lights?.set, programs: A.renderer.info.programs.length, calls: A.renderer.info.render.calls, tris: A.renderer.info.render.triangles }; });
    console.log(label.padEnd(16), JSON.stringify(r));
