      const A = window.__app, out = [];
      for (const p of A.renderer.info.programs) if (!window.__p0.has(p.cacheKey)) { out.push(p.name + ' | ' + p.cacheKey.slice(0, 400)); window.__p0.add(p.cacheKey); }
