cd "C:/Users/Client/AppData/Local/Temp/claude/e6d5994f4eac8fdb/cfbf6fb1-5faf-4660-9f00-508deb60dc5d/scratchpad" && cat > absets.mjs <<'EOF'
// A/B trong cùng trang: bộ đèn thật (day/night) vs 'full' (= hành vi cũ, mọi đèn hiện). node absets.mjs <repo> <dist>
import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';
import path from 'node:path';
const repo = process.argv[2], dist = process.argv[3];
const require = createRequire(path.join(repo, 'package.json'));
const { chromium } = require('playwright');
const lib = await import(pathToFileURL(path.join(repo, 'tests/lib.mjs')).href);
const srv = await lib.serveDir(dist);
const browser = await chromium.launch({ headless: true, args: ['--use-angle=d3d11', '--ignore-gpu-blocklist', '--enable-gpu', '--disable-gpu-vsync', '--disable-frame-rate-limit'] });
const { page } = await lib.openApp(browser, srv.url, { width: 1920, height: 1080 });
try {
  for (const n of [0, 1]) {
    await page.evaluate((n) => { const d = window.__app.dayNight; d.target = d.night = n; }, n);
    await lib.frames(page, 10);
    const r = await page.evaluate(async () => {
      const A = window.__app, R = A.renderer, gl = R.getContext(), ext = gl.getExtension('EXT_disjoint_timer_query_webgl2');
      const sleep = (ms) => new Promise((ok) => setTimeout(ok, ms));
      const lights = []; A.scene.traverse((o) => { if (o.isDirectionalLight || o.name === 'point-lights') lights.push(o); });
      const real = A.lights.set, p0 = R.info.programs.length;
      const t = async (full) => {
        const vis = lights.map((o) => o.visible);
        if (full) lights.forEach((o) => (o.visible = true));
        const draw = () => { R.info.reset(); R.render(A.scene, A.camera); };
        draw(); draw();
        const q = gl.createQuery(); gl.beginQuery(ext.TIME_ELAPSED_EXT, q);
        for (let i = 0; i < 12; i++) draw();
        gl.endQuery(ext.TIME_ELAPSED_EXT); gl.flush();
        const calls = R.info.render.calls;
        lights.forEach((o, i) => (o.visible = vis[i]));
        for (let k = 0; k < 400; k++) { await sleep(5); if (gl.getQueryParameter(q, gl.QUERY_RESULT_AVAILABLE)) break; }
        const ns = gl.getQueryParameter(q, gl.QUERY_RESULT); gl.deleteQuery(q);
        return [ns / 1e6 / 12, calls];
      };
      const o = { real: [], full: [] }; let c = {};
      for (let r = 0; r < 7; r++) for (const k of ['real', 'full']) { const [ms, calls] = await t(k === 'full'); o[k].push(ms); c[k] = calls; }
      const med = (a) => a.slice().sort((x, y) => x - y)[a.length >> 1];
      return { set: real, programsAdded: R.info.programs.length - p0, real: [+med(o.real).toFixed(2), +Math.min(...o.real).toFixed(2), +Math.max(...o.real).toFixed(2), c.real], full: [+med(o.full).toFixed(2), +Math.min(...o.full).toFixed(2), +Math.max(...o.full).toFixed(2), c.full] };
    });
    console.log(n ? 'ĐÊM' : 'NGÀY', JSON.stringify(r));
  }
} finally { await browser.close(); srv.close(); }
EOF
echo ok

